import { registerBlockType } from '@wordpress/blocks';
import { RichText, MediaUpload, BlockControls } from '@wordpress/editor';
import { Button } from '@wordpress/components';

registerBlockType('my-plugin/my-custom-block', {
    title: 'My Custom Block',
    icon: 'smiley',
    category: 'common',
    attributes: {
        title: {
            type: 'string',
            source: 'html',
            selector: 'h2',
        },
        content: {
            type: 'string',
            source: 'html',
            selector: 'p',
        },
        imageAlt: {
            attribute: 'alt',
            selector: '.my-image',
        },
        imageUrl: {
            attribute: 'src',
            selector: '.my-image',
        },
    },
    edit({ attributes, setAttributes }) {
        const { title, content, imageAlt, imageUrl } = attributes;

        const onChangeTitle = (newTitle) => {
            setAttributes({ title: newTitle });
        };

        const onChangeContent = (newContent) => {
            setAttributes({ content: newContent });
        };

        const onMediaUpload = (media) => {
            setAttributes({ imageUrl: media.url, imageAlt: media.alt });
        };

        const onRemoveImage = () => {
            setAttributes({ imageUrl: '', imageAlt: '' });
        };

        return (
